import { Component, forwardRef, input } from '@angular/core';
import { FormsModule, NG_VALUE_ACCESSOR } from '@angular/forms';
import { NzCheckboxModule } from 'ng-zorro-antd/checkbox';
import { HrmControl } from '../shared/hrm-control';

/** hrm-checkbox — CVA boolean. Nhãn qua content: <hrm-checkbox>Đồng ý</hrm-checkbox>
 *  indeterminate: hiển thị gạch ngang "chọn một phần" (dùng cho ô "chọn tất cả"). */
@Component({
  selector: 'hrm-checkbox',
  imports: [FormsModule, NzCheckboxModule],
  template: `
    <label nz-checkbox
      [ngModel]="value()"
      (ngModelChange)="emit($event)"
      [nzIndeterminate]="indeterminate()"
      [nzDisabled]="disabled()">
      <ng-content />
    </label>
  `,
  host: { class: 'hrm-checkbox' },
  providers: [{ provide: NG_VALUE_ACCESSOR, useExisting: forwardRef(() => HrmCheckbox), multi: true }],
})
export class HrmCheckbox extends HrmControl<boolean> {
  readonly indeterminate = input(false);
}
